CREATE PROCEDURE dbo.sp_UpdateStockWithLock
    @ProductID INT,
    @NewQuantity INT
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE dbo.Products
    SET StockQuantity = @NewQuantity
    WHERE ProductID = @ProductID;
END;

