CREATE OR REPLACE PROCEDURE dbo.sp_UpdateStockWithLock(
    p_ProductID INT,
    p_NewQuantity INT
)
LANGUAGE plpgsql
AS $$
BEGIN
    -- SET NOCOUNT ON equivalent: PostgreSQL doesn't send row counts by default in procedures

    UPDATE dbo.Products
    SET StockQuantity = p_NewQuantity
    WHERE ProductID = p_ProductID;

END;
$$;
